package com.example.campsitelottery

import java.util.Date

/**
 * [ReviewRepository] that keeps reviews in memory. Callbacks run synchronously.
 *
 * @param campsites campsites that can be reviewed.
 * @param reviews reviews that already exist, keyed by campsite ID.
 * @param clock supplies the time stamped on posted reviews.
 */
class InMemoryReviewRepository(
    campsites: List<Campsite> = emptyList(),
    reviews: Map<String, List<Review>> = emptyMap(),
    private val clock: () -> Date = { Date() },
) : ReviewRepository {

    private val owners = campsites.associate { it.campsiteId to it.ownerId }
    private val stored = mutableMapOf<Pair<String, String>, Review>().apply {
        reviews.forEach { (campsiteId, list) -> list.forEach { put(campsiteId to it.userId, it) } }
    }

    /** When set, every operation fails with this exception instead of running. */
    var failWith: Exception? = null

    override fun getReviews(
        campsiteId: String,
        onSuccess: (List<Review>) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        failWith?.let { return onFailure(it) }
        onSuccess(ReviewPolicy.sortNewestFirst(stored.filterKeys { it.first == campsiteId }.values.toList()))
    }

    override fun submitReview(
        campsiteId: String,
        userId: String,
        authorName: String,
        text: String,
        onSuccess: (Review) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        failWith?.let { return onFailure(it) }
        ReviewPolicy.validate(text)?.let { return onFailure(IllegalArgumentException(it)) }
        val ownerId = owners[campsiteId]
            ?: return onFailure(IllegalStateException("This campsite no longer exists."))
        if (!ReviewPolicy.canReview(ownerId, userId)) {
            return onFailure(IllegalStateException("You can't review your own campsite."))
        }
        val review = Review(
            userId = userId,
            authorName = authorName.trim(),
            text = ReviewPolicy.normalize(text),
            updatedAt = clock(),
        )
        stored[campsiteId to userId] = review
        onSuccess(review)
    }

    override fun removeReview(
        campsiteId: String,
        userId: String,
        expected: Review?,
        onSuccess: () -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        failWith?.let { return onFailure(it) }
        val review = stored[campsiteId to userId]
            ?: return onFailure(IllegalStateException("This review was already removed."))
        if (expected != null && expected != review) {
            return onFailure(IllegalStateException(ReviewPolicy.CHANGED_MESSAGE))
        }
        stored.remove(campsiteId to userId)
        onSuccess()
    }
}
